def solve(grid):
    # Return 0 for empty grid or grid with no columns
    if not grid:
        return 0
    # Check if there is at least one cell with a column
    if all(len(row) == 0 for row in grid):
        return 0
    n = len(grid)
    visited = set()
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(i,j):
        stack = [(i,j)]
        visited.add((i,j))
        while stack:
            x,y = stack.pop()
            for dx,dy in dirs:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < len(grid[nx]) and (nx,ny) not in visited and grid[nx][ny] == 1:
                    visited.add((nx,ny))
                    stack.append((nx,ny))
    count = 0
    for i,row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i,j) not in visited:
                count += 1
                dfs(i,j)
    return count

