def solve(s):
    """Return True if brackets in s are balanced and properly nested.
    Supports parentheses (), square brackets [], and curly braces {}.
    Ignores any other characters. Non-string inputs return False.
    """
    if not isinstance(s, str):
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
